INSERT INTO `classless_tree` (`id`, `name`, `description`, `sort_order`) VALUES
  (1, 'Fire', 'Destructive flame. The highest damage, and the least subtlety.', 10),
  (2, 'Frost', 'Cold and control. Slower, safer, relentless.', 20),
  (3, 'Arcane', 'Raw magic, bent to utility as often as to harm.', 30),
  (4, 'Holy', 'Light and mending. Keeps others upright.', 40),
  (5, 'Shadow', 'Rot, dread and slow ruin.', 50),
  (6, 'Nature', 'Growth, snare and restoration.', 60),
  (7, 'Sword Mastery', 'Weapon craft. Rewards closing the distance.', 70),
  (8, 'Defense', 'Shields, shouts and staying alive.', 80),
  (9, 'Stealth', 'Shadow and opportunity. Strike from where none look.', 90),
  (10, 'Marksmanship', 'Range, traps and patience.', 100);
